select r->'cpvTenders'->0 as first_new, json_array_length(r->'cpvTenders') as n_new, (select count(*) from json_array_elements(r->'cpvTenders') e where e->'republishes' is not null and e->>'republishes' <> 'null') as n_republished from (select public.follow_updates(null, null, null, current_date - 30, array['73200000-4','72222300-0','72225000-8','72200000-7','72000000-5','72212000-4'], array['EL3']) as r) q;
select json_array_length(public.follow_updates(array['26PROC020026993'], null, null, current_date - 60)->'tenders') as old_tender_has_events, left((public.follow_updates(array['26PROC020026993'], null, null, current_date - 60)->'tenders'->0)::text, 700) as events
